import { readFileSync } from 'node:fs';
import { expect, test, type Page } from '@playwright/test';
import { goToApp, navigateToView } from './fixtures';
import { readRows, seedRows } from './client-lifecycle-fixtures';

// Generated by the hosted build, outside the publication directory. These are
// actual rendered-module identities, not assumptions about vendor filenames.
const budget: { deferred: Record<string, string[]> } = JSON.parse(readFileSync(
  new URL('../node_modules/.cache/threatcaddy/startup-budget.json', import.meta.url), 'utf8'));
test.use({ serviceWorkers: 'block' });

async function observe(page: Page, baseURL: string | undefined) {
  if (!baseURL) throw new Error('A loopback test origin is required');
  const origin = new URL(baseURL).origin;
  await page.context().route(/^https?:\/\//, route => new URL(route.request().url()).origin === origin ? route.continue() : route.abort());
  const requested = new Set<string>();
  const errors: string[] = [];
  page.on('request', request => requested.add(new URL(request.url()).pathname.slice(1)));
  page.on('pageerror', error => errors.push(error.message));
  const loaded = (feature: string) => budget.deferred[feature].some(file => requested.has(file));
  return { requested, errors, loaded };
}

async function seedObservation(page: Page) {
  const now = Date.now();
  const shared = { tags: [], archived: false, trashed: false, createdAt: now, updatedAt: now };
  await seedRows(page, {
    notes: [{ ...shared, id: 'lazy-note', title: 'Fictional graph note', content: 'Synthetic observation', pinned: false }],
    timelineEvents: [{ ...shared, id: 'lazy-event', title: 'Fictional map observation', description: 'Synthetic coordinates',
      timestamp: now, eventType: 'other', confidence: 'medium', assets: [], mitreAttackIds: [],
      latitude: 0, longitude: 0, linkedNoteIds: ['lazy-note'], linkedTaskIds: [], linkedIOCIds: [], starred: false }],
  });
}

test('heavy editors stay out of startup and still render and persist when opened', async ({ page, baseURL }) => {
  const { errors, loaded } = await observe(page, baseURL);
  await goToApp(page);
  await seedObservation(page);
  await page.reload();
  await expect(page.locator('[data-tour="header"]')).toBeVisible();
  await page.waitForLoadState('networkidle');
  for (const feature of Object.keys(budget.deferred)) expect(loaded(feature), `${feature} must remain deferred`).toBe(false);

  await page.locator('[data-tour="header"]').getByRole('button', { name: /Create new/i }).click();
  await page.getByRole('menuitem', { name: /Whiteboard/i }).click();
  await expect(page.locator('.excalidraw canvas').first()).toBeVisible();
  await page.getByPlaceholder('Whiteboard name').fill('Fictional deferred whiteboard');
  await expect.poll(async () => (await readRows(page, ['whiteboards'])).whiteboards[0]?.name).toBe('Fictional deferred whiteboard');
  expect(loaded('whiteboard')).toBe(true);

  await navigateToView(page, 'Graph');
  await expect(page.getByRole('img', { name: 'Investigation graph visualization' })).toBeVisible();
  await expect.poll(() => loaded('graph')).toBe(true);
  expect(loaded('map')).toBe(false);

  await navigateToView(page, 'Timeline');
  await page.getByRole('button', { name: /Map view/i }).click();
  await expect(page.locator('.leaflet-container')).toBeVisible();
  await expect(page.locator('.leaflet-marker-icon').first()).toBeVisible();
  expect(loaded('map')).toBe(true);
  expect(errors).toEqual([]);
});

test('mobile event details load their map only after selecting a coordinate-bearing event', async ({ page, baseURL }, testInfo) => {
  const { requested, errors, loaded } = await observe(page, baseURL);
  await goToApp(page);
  await seedObservation(page);
  await page.setViewportSize({ width: 390, height: 844 });
  requested.clear();
  await page.reload();
  await page.getByRole('button', { name: /Events This Week/i }).click();
  expect(loaded('map')).toBe(false);
  await page.getByRole('button', { name: /Fictional map observation/ }).click();
  await expect(page.getByRole('heading', { name: 'Fictional map observation', exact: true })).toBeVisible();
  await expect(page.locator('.leaflet-container')).toBeVisible();
  await expect(page.locator('.leaflet-marker-icon')).toBeVisible();
  await expect(page.getByText('0 of 0', { exact: true })).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'Investigation', exact: true })).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'Prev', exact: true })).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'Next', exact: true })).toHaveCount(0);
  expect(loaded('map')).toBe(true);
  expect(errors).toEqual([]);
  await page.screenshot({ path: testInfo.outputPath('deferred-mobile-map.png') });
  await page.getByRole('button', { name: 'Events This Week', exact: true }).click();
  await expect(page.getByRole('button', { name: /Fictional map observation/ })).toBeVisible();
});
